public class Bar {
    public void foo () {
        int localVariableB;
        int localVariableA; // incorrect, variable A comes before variable B lexicographically
    }
}

public class Bar {
    public void foo () {
        int localVariable_a;
        int localVariable_B; // incorrect, B comes before a with a case-sensitive sort
    }
}

public class Bar {
    public void foo () {
        int B_var;
        int a_var; // incorrect, 'a' comes before 'B' in a case-insensitive sort
    }
}

public class Bar {
    public void foo () {
        String localVariable1;
        int localVariable2; // incorrect, int comes before String with a case-insensitive sort
    }
}

public class Bar {
    public void foo () {
        int localVariable1;
        String localVariable2; // incorrect, String comes before int with a case-sensitive sort
    }
}

public class Bar {
    public void foo () {
        String localVariable2;
        String localVariable1; // incorrect, variables of the same type should be ordered by name
    }
}

public class Bar {
    public void foo () {
        int localVariable2;
        int localVariable1; // incorrect, variables of the same type should be sorted according to name
        String localVariable3; // incorrect, String comes before int with a case-sensitive sort
    }
}

public class Bar {
    public void foo () {
        int localVariable2;
        var localVariable1 = 1;
        XCustomType localVariable3; // incorrect, X comes after v but var should always come last
    }
}

public class Bar {
    public Bar () {
        super();
        int localVariable1;
    }

    public Bar(int a) {
        this();
        String localVariable2;
    }
}

public class Bar {
    public void foo () {
        int a, d = 2;
        int c, e = 1;
        int b = 3, f; // incorrect, b comes before c

        int p = 2, y;
        int l = 3, z = 4; // incorrect, l comes before p
    }
}

public class Bar {
    public void foo () {
        int[] a;
        int b, c[]; // incorrect, int comes before int[]
    }

    public void foo2 () {
        int a[], b;
        int c; // correct, only the overall type is considered
    }
}

public class Bar {
    int a = 1;
    int[] b = new int[5];
    var x = 3;
    String y = "15"; // incorrect, var comes last
    JavaNode z; // incorrect, J comes before S
}

public class Bar {
    int b = 1;
    int a = 2; // incorrect, b before a

    void foo () {
        int d;
        int c; // correct, local variables are ignored
    }
}

public class Bar {
    int b = 1;
    int a = 2; // correct, fields are ignored

    void foo () {
        int d;
        int c; // incorrect, c comes before d
    }
}

public class Bar {
    public void foo (boolean flag) {
        if (flag) {
            int b = 1;
            int a = 2; // incorrect, a should come before b in this block
        }
    }
}

public class Bar {
    public void foo (int value) {
        switch (value) {
            case 1:
                int second;
                int first; // incorrect, first comes before second
        }
    }
}

public class Bar {
    public void foo () {
        int z = 1;
        System.out.println("Doing some work");
        int a = 2; // correct, this is no longer the top of the block
    }
}

public class Bar {
    int z = 1;

    public void doSomething() {
    }

    int a = 2; // correct, field is declared after a method so it is ignored
}

public class Bar {
    public void foo () {
        final String b = "test";
        final int a = 1; // incorrect, 'int' comes before 'String' despite 'final'
    }
}

public class Bar {
    public void foo () {
        int x;
        var b = "hello";
        var a = 123; // incorrect, both are 'var', so 'a' must come before 'b'
    }
}

public class Bar {
    static {
        int b = 1;
        int a = 2; // incorrect, static initializer is a block scope
    }
}
